package ch.famfrehner.bonflow.ordering;

import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

import jakarta.persistence.CascadeType;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.Id;
import jakarta.persistence.OneToMany;
import jakarta.persistence.OrderBy;
import jakarta.persistence.Table;
import jakarta.persistence.Version;

/**
 * The aggregate root. The id is generated by the app, which makes submitting idempotent.
 * Items are only ever added (follow-up submissions) or cancelled, never edited.
 */
@Entity
@Table(name = "customer_order")
class CustomerOrder {

    @Id
    private UUID id;

    @Column(name = "dining_table_id", nullable = false)
    private Long diningTableId;

    @Column(name = "waiter_id", nullable = false)
    private Long waiterId;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 20)
    private OrderStatus status;

    @Column(name = "created_at", nullable = false)
    private Instant createdAt;

    @Column(name = "submitted_at")
    private Instant submittedAt;

    @Column(columnDefinition = "text")
    private String note;

    @Version
    private Long version;

    @OneToMany(mappedBy = "order", cascade = CascadeType.ALL, orphanRemoval = true)
    @OrderBy("id")
    private List<OrderItem> items = new ArrayList<>();

    protected CustomerOrder() {
    }

    CustomerOrder(UUID id, long diningTableId, long waiterId, Instant now, String note) {
        this.id = id;
        this.diningTableId = diningTableId;
        this.waiterId = waiterId;
        this.status = OrderStatus.SUBMITTED;
        this.createdAt = now;
        this.submittedAt = now;
        this.note = note;
    }

    void addItem(OrderItem item) {
        items.add(item);
    }

    /** Highest submission number so far (0 for an order without items). */
    int lastSubmissionNo() {
        return items.stream().mapToInt(OrderItem::getSubmissionNo).max().orElse(0);
    }

    boolean hasActiveItems() {
        return items.stream().anyMatch(i -> i.getStatus() == ItemStatus.ACTIVE);
    }

    void cancel() {
        status = OrderStatus.CANCELLED;
    }

    void complete() {
        status = OrderStatus.COMPLETED;
    }

    UUID getId() {
        return id;
    }

    Long getDiningTableId() {
        return diningTableId;
    }

    Long getWaiterId() {
        return waiterId;
    }

    OrderStatus getStatus() {
        return status;
    }

    Instant getCreatedAt() {
        return createdAt;
    }

    Instant getSubmittedAt() {
        return submittedAt;
    }

    String getNote() {
        return note;
    }

    List<OrderItem> getItems() {
        return items;
    }
}
